import {
  Clock3,
  House,
  Store,
  Truck,
  UserRound,
  Utensils,
} from "lucide-react-native";
import { useEffect, useMemo, useState } from "react";
import {
  ScrollView,
  useColorScheme,
  useWindowDimensions,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import {
  buildRouteUrl,
  deliveryMeals,
  dropoff,
  mapView,
  parseOsrmRoute,
  pickup,
  progressFraction,
  routeStyle,
  type OsrmRouteData,
} from "./data";
import { formatDistance, formatDuration } from "./utils";

import { Badge } from "@/atoms/Badge";
import { Button } from "@/atoms/Button";
import { Icon } from "@/atoms/Icon";
import { Text } from "@/atoms/Text";
import { Card, CardContent, CardHeader, CardTitle } from "@/molecules/Card";
import {
  Map,
  MapMarker,
  MapRoute,
  MarkerContent,
  MarkerLabel,
} from "@/atoms/Map";

export default function Page() {
  const [routeData, setRouteData] = useState<OsrmRouteData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const colorScheme = useColorScheme();
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const isCompact = width < 768;
  const pagePadding = isCompact ? 12 : 32;
  const remainingRouteColor =
    colorScheme === "dark"
      ? routeStyle.remaining.color.dark
      : routeStyle.remaining.color.light;

  useEffect(() => {
    async function fetchRoute() {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch(buildRouteUrl(pickup, dropoff));
        const json = (await response.json()) as unknown;
        const parsed = parseOsrmRoute(json);
        if (!parsed) {
          setError("Unable to load route data right now.");
          return;
        }
        setRouteData(parsed);
      } catch {
        setError("Unable to load route data right now.");
      } finally {
        setLoading(false);
      }
    }

    void fetchRoute();
  }, []);

  const progressCoordinates = useMemo(() => {
    const total = routeData?.coordinates?.length ?? 0;
    const progressCount = Math.max(2, Math.floor(total * progressFraction));
    return routeData?.coordinates?.slice(0, progressCount) ?? [];
  }, [routeData]);

  const courierPosition = progressCoordinates[progressCoordinates.length - 1];

  return (
    <View
      className="flex-1 items-center justify-center p-3 md:p-8"
      style={{ paddingBottom: pagePadding + insets.bottom }}
    >
      <View
        className={
          isCompact
            ? "bg-sidebar h-full w-full flex-col overflow-hidden rounded-xl border border-border"
            : "bg-sidebar max-h-[720px] w-full max-w-5xl flex-row overflow-hidden rounded-xl border border-border"
        }
      >
        <ScrollView
          className={isCompact ? "min-h-0 flex-1" : "min-w-0 flex-1"}
          contentContainerClassName="p-5 pb-8 md:p-6"
          showsVerticalScrollIndicator={false}
        >
          <View className="gap-1">
            <Text className="text-2xl font-semibold tracking-tight">
              Track Delivery
            </Text>
            <Text className="text-muted-foreground text-sm">
              Mon Feb 10 - 2-3 PM
            </Text>
          </View>

          <Card className="mt-5">
            <CardHeader>
              <CardTitle className="font-medium">
                Order items ({deliveryMeals.length})
              </CardTitle>
            </CardHeader>
            <CardContent className="gap-5">
              {deliveryMeals.map((meal) => (
                <View
                  key={meal.name}
                  className="flex-row items-center gap-3"
                >
                  <View className="bg-muted size-8 items-center justify-center rounded-full">
                    <Icon
                      as={Utensils}
                      size={16}
                      className="text-muted-foreground"
                    />
                  </View>
                  <View className="min-w-0 flex-1">
                    <Text
                      className="pb-1 text-sm font-medium"
                      numberOfLines={1}
                    >
                      {meal.name}
                    </Text>
                    <Text className="text-muted-foreground text-xs">
                      {meal.price}
                    </Text>
                  </View>
                  <Badge
                    variant="secondary"
                    className="h-6 rounded-full px-2.5"
                  >
                    <Text className="text-xs">x{meal.quantity}</Text>
                  </Badge>
                </View>
              ))}
              <View className="border-border/60 flex-row items-center justify-between border-t pt-3">
                <Text className="text-muted-foreground text-sm">
                  Bundle total
                </Text>
                <Text className="text-sm font-medium">$189.00</Text>
              </View>
            </CardContent>
          </Card>

          <View className="mt-4 flex-row gap-3">
            <Card className="flex-1">
              <CardContent className="gap-2">
                <Text className="text-muted-foreground text-sm">
                  Pickup confirmed
                </Text>
                <Text className="text-sm font-medium">
                  Mon, Feb 10 at 1:48 PM
                </Text>
              </CardContent>
            </Card>
            <Card className="flex-1">
              <CardContent className="gap-2">
                <Text className="text-muted-foreground text-sm">
                  Remaining travel
                </Text>
                <Text className="text-sm font-medium">
                  {formatDuration(routeData?.duration)}
                  <Text className="text-muted-foreground font-normal">
                    {" · "}
                    {formatDistance(routeData?.distance)}
                  </Text>
                </Text>
              </CardContent>
            </Card>
          </View>

          {error ? (
            <View className="mt-3">
              <Text className="text-destructive text-xs">{error}</Text>
            </View>
          ) : null}

          <View className="mt-6 flex-row flex-wrap items-center gap-2">
            <Button size="sm">
              <Icon
                as={Clock3}
                size={16}
              />
              <Text>View timeline</Text>
            </Button>
            <Button
              variant="outline"
              size="sm"
            >
              <Icon
                as={UserRound}
                size={16}
              />
              <Text>Contact courier</Text>
            </Button>
          </View>
        </ScrollView>

        <View
          className={
            isCompact
              ? "relative h-[42%] min-h-72 w-full shrink-0 overflow-hidden border-t border-border"
              : "relative min-h-[520px] min-w-0 flex-1 overflow-hidden"
          }
        >
          <Map
            loading={loading}
            viewport={{
              center: mapView.center,
              zoom: mapView.zoom,
            }}
            minZoom={mapView.minZoom}
            maxZoom={mapView.maxZoom}
          >
            <MapRoute
              id="delivery-full-route"
              coordinates={routeData?.coordinates ?? []}
              color={remainingRouteColor}
              width={routeStyle.remaining.width}
              opacity={routeStyle.remaining.opacity}
              interactive={false}
            />
            <MapRoute
              id="delivery-progress-route"
              coordinates={progressCoordinates}
              color={routeStyle.progress.color}
              width={routeStyle.progress.width}
              opacity={routeStyle.progress.opacity}
              interactive={false}
            />

            {courierPosition ? (
              <MapMarker
                longitude={courierPosition[0]}
                latitude={courierPosition[1]}
                offset={[0, 10]}
              >
                <MarkerContent>
                  <View
                    className="size-9 items-center justify-center rounded-full shadow-md"
                    style={{ backgroundColor: routeStyle.progress.color }}
                  >
                    <Icon
                      as={Truck}
                      size={16}
                      className="text-white"
                    />
                  </View>
                  <MarkerLabel className="bg-popover border-border mb-1.5 rounded-md border px-2 py-1 shadow-md">
                    <Text
                      className="text-popover-foreground text-xs font-medium"
                      numberOfLines={1}
                    >
                      {formatDuration(routeData?.duration)} away
                    </Text>
                  </MarkerLabel>
                </MarkerContent>
              </MapMarker>
            ) : null}

            <MapMarker
              longitude={pickup.lng}
              latitude={pickup.lat}
            >
              <MarkerContent>
                <View className="size-7 items-center justify-center rounded-full bg-emerald-500 shadow-md">
                  <Icon
                    as={Store}
                    size={14}
                    className="text-white"
                  />
                </View>
              </MarkerContent>
            </MapMarker>

            <MapMarker
              longitude={dropoff.lng}
              latitude={dropoff.lat}
            >
              <MarkerContent>
                <View className="size-7 items-center justify-center rounded-full bg-rose-500 shadow-md">
                  <Icon
                    as={House}
                    size={14}
                    className="text-white"
                  />
                </View>
              </MarkerContent>
            </MapMarker>
          </Map>
        </View>
      </View>
    </View>
  );
}

import { z } from "zod";

export interface DeliveryMeal {
  name: string;
  price: string;
  quantity: number;
}

export interface OsrmRouteData {
  coordinates: [number, number][];
  duration: number;
  distance: number;
}

export const deliveryMeals: DeliveryMeal[] = [
  { name: "Spicy Tofu Grain Bowl", price: "$44.00", quantity: 1 },
  { name: "Herb Chicken Rice Box", price: "$58.00", quantity: 2 },
  { name: "Roasted Veggie Wrap", price: "$29.00", quantity: 1 },
];

/** Pickup (origin) and dropoff (destination) coordinates. */
export const pickup = { lng: -122.4185, lat: 37.7645 };
export const dropoff = { lng: -122.434, lat: 37.7475 };

/** Initial map viewport. */
export const mapView = {
  center: [-122.4263, 37.756] as [number, number],
  zoom: 13.6,
  minZoom: 12,
  maxZoom: 15,
};

/** Fraction of the route the courier has already covered (0–1). */
export const progressFraction = 0.62;

const osrmRouteGeometrySchema = z.object({
  coordinates: z.array(z.tuple([z.number(), z.number()])),
});

const osrmRouteSchema = z.object({
  duration: z.number(),
  distance: z.number(),
  geometry: osrmRouteGeometrySchema,
});

const osrmResponseSchema = z.object({
  routes: z.array(osrmRouteSchema).min(1),
});

export function parseOsrmRoute(data: unknown): OsrmRouteData | null {
  const result = osrmResponseSchema.safeParse(data);
  if (!result.success) {
    return null;
  }
  const route = result.data.routes[0];
  return {
    coordinates: route.geometry.coordinates,
    duration: route.duration,
    distance: route.distance,
  };
}

/**
 * OSRM demo routing endpoint. Swap in your own routing service by returning a
 * URL that responds with GeoJSON route geometry.
 */
export function buildRouteUrl(
  from: { lng: number; lat: number },
  to: { lng: number; lat: number },
): string {
  return `https://router.project-osrm.org/route/v1/driving/${String(from.lng)},${String(from.lat)};${String(to.lng)},${String(to.lat)}?overview=full&geometries=geojson`;
}

/**
 * Route line styling. WebGL paint can't read CSS variables, so colors are
 * concrete hex. `progress` highlights the covered path; `remaining` is themed
 * for the road still ahead.
 */
export const routeStyle = {
  progress: { color: "#3b82f6", width: 6, opacity: 0.95 },
  remaining: {
    width: 5.2,
    opacity: 0.5,
    color: { light: "#6b7280", dark: "#9ca3af" },
  },
} as const;

export function formatDistance(meters?: number): string {
  if (!meters) return "--";
  if (meters < 1000) return `${String(Math.round(meters))} m`;
  return `${(meters / 1000).toFixed(1)} km`;
}

export function formatDuration(seconds?: number): string {
  if (!seconds) return "--";
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${String(minutes)} min`;
  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;
  return `${String(hours)}h ${String(remainingMinutes)}m`;
}
